// By default, destructors are noexcept(true)
class SafeWidget {
public:
    ~SafeWidget() = default; // Implicitly noexcept
};

// A class with an explicitly throwing destructor
class UnsafeComponent {
public:
    ~UnsafeComponent() noexcept(false) {};
};

// A class containing an unsafe member is also not noexcept
class UnsafeWidget {
    UnsafeComponent member;
public:
    ~UnsafeWidget() = default; // Implicitly noexcept(false)
};

static_assert(std::is_nothrow_destructible<SafeWidget>::value, "SafeWidget dtor should be noexcept");
static_assert(!std::is_nothrow_destructible<UnsafeWidget>::value, "UnsafeWidget dtor should not be noexcept");
